(() => {
  "use strict";
  const raw = [["Which statement best describes the Internet of Things (IoT)?","A network of physical objects that sense, compute, and exchange data|Only desktop computers connected to the web|A database containing sensor readings|A network that works without communication protocols",0,"IoT combines physical objects, sensing/actuation, computation, and connectivity to support monitoring or action."],["A sensor produces 240 bytes every 2 seconds. Ignoring overhead, what is its average data rate?","120 bytes/s|240 bytes/s|480 bytes/s|60 bytes/s",0,"Average rate is data produced divided by elapsed time: 240 / 2 = 120 bytes/s."],["A device is ON for 15 ms and OFF for 45 ms in each cycle. What is its duty cycle?","25%|33.3%|75%|60%",0,"Duty cycle = ON time / total cycle time × 100 = 15 / 60 × 100 = 25%."],["A 2,400-bit packet is sent over a 800 bit/s link. Ignoring overhead and propagation, how long is transmission?","3 seconds|0.3 seconds|30 seconds|1.6 seconds",0,"Transmission time = packet bits / bit rate = 2400 / 800 = 3 seconds."],["Which factor directly increases packet transmission time when link rate stays fixed?","Larger packet size|Lower propagation distance|Fewer network hops after transmission|Higher receiver sensitivity",0,"Transmission time depends on packet size and link bit rate; more bits take longer at a fixed rate."],["Which is the strongest reason to use UDP for a small real-time sensor update?","Low protocol overhead when occasional loss is acceptable|Guaranteed in-order delivery|Automatic retransmission of every lost datagram|Built-in congestion-free delivery",0,"UDP has a small header and no built-in reliability or ordering, useful when timeliness matters more than recovering every update."],["Which statement about TCP is correct?","It provides reliable, ordered byte-stream delivery|It never retransmits lost data|It has no connection setup concept|It preserves application message boundaries automatically",0,"TCP provides reliable ordered byte-stream delivery; applications must frame messages themselves."],["A temperature monitor sends a fresh reading every second. A delayed reading is less useful than the newest one. Which design choice is most appropriate?","Use timestamps and prefer recent readings; UDP may fit|Queue every reading forever until delivered|Disable timestamps to reduce metadata|Wait for all old readings before displaying the newest",0,"For freshness-oriented telemetry, timestamps and latest-value handling can be more useful than waiting for stale packets."],["Which is an example of an actuator rather than a sensor?","A relay that switches a pump|A thermistor measuring temperature|A photodiode measuring light|A humidity sensor",0,"An actuator changes the physical world; a relay can switch a pump, while the others measure conditions."],["What is the main role of a sensor in an IoT system?","Measure a physical or environmental quantity|Route packets between IP networks|Store every cloud backup|Authenticate all users",0,"Sensors convert a physical quantity such as temperature, light, or pressure into a measurable signal."],["Which is a common IoT interoperability challenge?","Devices use different data formats and protocols|All devices have identical interfaces|Every vendor uses the same units|All sensors generate the same sampling rate",0,"Interoperability is difficult when devices differ in protocols, data models, units, interfaces, and vendor implementations."],["In machine-to-machine (M2M) communication, what is emphasized?","Machines exchange data or commands with limited human intervention|Humans must manually approve every packet|Only social media messages are exchanged|Devices cannot act on received data",0,"M2M enables machines to communicate and coordinate directly, often supporting automated monitoring and control."],["What distinguishes an ad hoc network?","Nodes can form a network without relying on fixed infrastructure|It must use one permanent central router|It can only contain wired desktop computers|Every route is manually configured and never changes",0,"Ad hoc networks can form dynamically without fixed infrastructure; nodes may also forward traffic for others."],["In a wireless sensor network, why is energy efficiency important?","Many sensor nodes run on limited batteries and may be hard to service|Radio transmission consumes no energy|Battery capacity increases with every packet|Energy matters only at the base station",0,"Sensor nodes often have limited batteries and may be deployed in places where frequent replacement is impractical."],["A sensor node spends 10 ms active and 90 ms asleep per 100 ms cycle. What fraction of the cycle is asleep?","90%|10%|50%|100%",0,"Sleep fraction is 90 / 100 × 100 = 90%; active and sleep fractions sum to 100%."],["What is latency in a communication system?","The time taken for data to travel from source to destination or through a process|The number of devices in a network|The amount of stored data|The maximum battery voltage",0,"Latency is delay between an event or transmission and its arrival or completion."],["Which action most directly reduces the amount of data sent from a sensor node?","Aggregate or summarize readings locally when suitable|Increase the number of duplicate packets|Send every raw sample repeatedly|Add unnecessary headers",0,"Local aggregation can reduce transmissions by combining or summarizing readings before forwarding."],["A gateway receives the same event three times with the same event ID. What should a robust pipeline often do?","Deduplicate using the event ID|Count all copies as separate real-world events|Delete every event from that sensor|Change the event timestamp randomly",0,"Stable event identifiers help identify retransmitted or duplicated messages without counting them multiple times."],["What is a typical role of an IoT gateway?","Bridge local devices or protocols to upstream networks/services|Replace every sensor's physical measurement|Guarantee that batteries never discharge|Act only as a user interface",0,"A gateway can connect constrained/local devices to IP networks or cloud services and may translate protocols or aggregate data."],["Why are timestamps useful in IoT telemetry?","They help order readings and reason about freshness and delays|They guarantee that every packet arrives|They encrypt the payload|They replace sensor calibration",0,"Timestamps support ordering, freshness checks, trend analysis, and latency estimation when clocks are sufficiently synchronized."],["On an Arduino, what does setting a digital output pin to HIGH generally mean?","Drive the pin to its logic-high voltage level|Read an analog voltage automatically|Turn the board off|Start a UDP server",0,"For a configured digital output, HIGH drives the pin toward the board's logic-high voltage; exact voltage depends on the board."],["Why should a sensor be calibrated?","To improve the relationship between its output and the true measured quantity|To increase Wi-Fi bandwidth|To eliminate all network latency|To turn analog data into a password",0,"Calibration compares sensor readings with a reference and helps correct systematic measurement error."],["A DHT sensor reports humidity 101%. What is the best first interpretation?","Treat it as invalid or suspicious and validate the reading|Accept it as normal relative humidity|Convert it to 101 degrees Celsius|Assume the network protocol changed the physical humidity",0,"Relative humidity is normally bounded from 0% to 100%; values outside the expected range should be checked."],["Which board is commonly used as a small single-board computer capable of running Linux?","Raspberry Pi|A passive thermistor|A relay module alone|A bare photodiode",0,"Raspberry Pi boards can run an operating system such as Linux and execute applications, network clients, and servers."],["Compared with a typical microcontroller board, a Raspberry Pi is often better suited to which task?","Running a higher-level OS and networked Python applications|Operating with no operating system in all configurations|Measuring temperature without any sensor|Guaranteeing hard real-time timing in every setup",0,"A Raspberry Pi is a small general-purpose computer, commonly used for OS-based applications and networking; timing guarantees depend on system design."],["A Raspberry Pi UDP client sends sensor readings to a server. Which information does the client need to target the server?","The destination IP address and UDP port|Only the sensor's color|The server's screen resolution|The number of lines in its source code",0,"A UDP datagram is directed using an IP address and destination port, along with the transport protocol."],["What does a UDP server commonly do before receiving datagrams on a known port?","Create a UDP socket and bind it to the local address/port|Open a TCP listening connection only|Disable all network interfaces|Convert every packet to an image",0,"A server normally creates a UDP socket and binds it to a local port so the operating system can deliver datagrams there."],["Why can UDP datagrams arrive out of order or be lost?","UDP itself does not provide delivery, ordering, or retransmission guarantees|UDP always waits for all packets before delivery|Every router guarantees UDP ordering|UDP requires a connection handshake that sorts packets",0,"UDP is connectionless and does not itself implement reliable ordered delivery; the network may drop or reorder packets."],["A Python sensor logger writes one row every 5 seconds for 8 minutes. How many rows are recorded if it starts at time zero and includes the reading at exactly 8 minutes?","97|96|80|48",0,"Eight minutes is 480 seconds, giving readings at 0, 5, …, 480: 480/5 + 1 = 97 rows."],["Which is a good reason to log IoT sensor data locally as well as transmit it?","Local logs can preserve observations during intermittent connectivity|Local logging guarantees cloud availability|It eliminates the need for timestamps|It makes sensors immune to power failure",0,"A local buffer or log can preserve readings during network outages, subject to local storage and power limits."],["In SDN, which plane makes high-level decisions about network behavior?","Control plane|Data plane|Physical sensing plane only|Presentation plane",0,"The control plane decides forwarding behavior and policy; the data plane forwards packets according to installed rules."],["What is the primary role of the SDN data plane?","Forward packets using rules installed or managed by the control plane|Create every network policy independently|Train all machine-learning models|Measure only battery voltage",0,"The data plane performs packet forwarding based on flow entries or forwarding rules."],["In SDN, what does a northbound API typically connect?","The controller to applications or orchestration software|A switch's power cable to its battery|Two sensor pins directly|A user to a physical actuator without software",0,"Northbound interfaces expose controller capabilities to applications and higher-level services."],["What does a southbound interface commonly enable in SDN?","Communication between the controller and forwarding devices|Communication only between a user and a dashboard|Charging a sensor battery|Replacing all application logic",0,"Southbound protocols or APIs let a controller program or query switches and other network elements."],["What is OpenFlow commonly associated with?","A protocol for controller-to-switch communication and flow-table control|A humidity measurement standard|A Python package for drawing graphs only|A battery chemistry",0,"OpenFlow has been used to let an SDN controller interact with switch flow tables."],["What is TCAM useful for in many networking devices?","Fast matching of packet fields against rules, often in parallel|Storing video recordings permanently|Calibrating analog sensors|Compressing a Python script",0,"Ternary content-addressable memory can perform fast matching with 0, 1, and don't-care bits, useful for packet classification."],["Why can SDN help manage heterogeneous IoT networks?","Centralized programmability can coordinate policies across different forwarding devices|It removes the need for all communication links|It makes every sensor use the same physical connector|It guarantees zero packet loss",0,"SDN can simplify policy and traffic management through programmable control, though interoperability still needs suitable interfaces."],["Which is a key design concern in SDN-based wireless sensor networks?","Control overhead and energy consumption on constrained nodes|Making all nodes transmit continuously|Avoiding all network measurements|Using only high-power radios",0,"SDN control messaging and state must be designed carefully because sensor nodes may have limited energy and processing resources."],["Why is separating control and data planes useful?","Control logic can evolve independently of packet-forwarding mechanisms|Packets no longer need destination addresses|It eliminates the need for network devices|Every application must control each wire manually",0,"Separation supports programmability and centralized or logically centralized policy without requiring each forwarding device to make every policy decision."],["What is a likely use of a flow table in a programmable switch?","Match packet fields and apply actions such as forward or drop|Store a user's password in plain text|Record the physical temperature of a room|Set the sensor's calibration constant automatically",0,"Flow entries typically combine match criteria, priority, and actions such as forwarding, dropping, or modifying packets."],["What is a risk of a single centralized SDN controller without redundancy?","It may become a failure or bottleneck point|It makes all network links wireless|It prevents policy updates|It guarantees all packets arrive faster",0,"A logically centralized controller can be a bottleneck or failure concern unless the architecture provides resilience and scaling."],["In a smart-grid monitoring scenario, what is a typical role of IoT sensors?","Measure grid conditions such as current, voltage, or equipment status|Generate electricity by measuring it|Replace protective relays in every design|Guarantee no outages",0,"Sensors provide observations that monitoring and control systems can use to understand grid conditions."],["If 60 smart meters each send one record every 10 seconds, how many records are generated in one minute in total?","360|60|600|6",0,"Each meter sends 6 records per minute, so 60 × 6 = 360 records."],["Why is data quality important before analyzing IoT data?","Missing, duplicated, or implausible readings can distort conclusions|Data quality changes the physical sensor into an actuator|Analysis is always correct regardless of input|Cleaning data removes the need to understand context",0,"Analytics can be misleading when inputs contain missing, duplicated, stale, or invalid readings."],["What is a common purpose of an IoT data aggregator?","Combine readings from multiple sources into a useful summary or stream|Increase every reading's value arbitrarily|Prevent any device from communicating|Replace all sensors with one hard-coded number",0,"An aggregator combines or summarizes data, often reducing volume and helping downstream analysis."],["A device sends 1,000 records; 80 are duplicates. How many unique records remain after perfect deduplication?","920|1,080|80|1,000",0,"Unique count is 1000 − 80 = 920 when exactly 80 records are duplicates beyond their originals."],["What is a time-series dataset?","Observations associated with timestamps, often ordered over time|A list of random passwords|A graph with no measured values|A collection that cannot contain numeric data",0,"Time-series data records measurements or events with time information, supporting trends, seasonality, and temporal analysis."],["Which visualization is usually appropriate for temperature measured hourly across a day?","A line chart with time on the horizontal axis|A pie chart of unrelated categories only|A word cloud|A single unlabelled number",0,"A line chart helps show how a numeric measurement changes over time."],["Why might an IoT analytics pipeline use edge processing?","To reduce response time or upstream data volume for suitable tasks|To guarantee the cloud never fails|To make every sensor physically larger|To remove all local computation",0,"Processing near the data source can reduce latency, bandwidth use, or dependence on a continuous cloud connection."],["What does latency-sensitive monitoring prioritize?","Timely delivery or action, not only total throughput|Maximum file size regardless of delay|Collecting every historical record before reacting|Increasing the number of hops without purpose",0,"In time-sensitive applications, the age of the information and response delay can matter more than bulk throughput."],["What is throughput?","The amount of data successfully delivered or processed per unit time|The delay of one packet only|The number of sensors' brand names|The battery voltage at rest",0,"Throughput measures successful data transfer or processing over time, commonly expressed in bits/s or records/s."],["A system has high throughput but a 12-second delay. Which statement is reasonable?","It can move lots of data overall yet still be unsuitable for urgent control|High throughput always means zero latency|Latency and throughput are identical quantities|A 12-second delay proves no data was transmitted",0,"Throughput and latency are different: a system may transfer large volumes while still delivering individual results too late."],["Which is the best example of closed-loop IoT control?","A thermostat measures temperature and switches heating based on the result|A sensor records data that nobody ever uses|A dashboard displays a fixed image|A network cable is labeled",0,"Closed-loop control uses measurements to decide actions, then can measure again to evaluate the effect."],["Why should an IoT system validate incoming measurements?","To catch impossible values, malformed data, and sensor faults before use|To make every value larger|To avoid defining units|To guarantee that a faulty sensor becomes accurate",0,"Validation catches data that violates expected ranges, formats, units, or application constraints."],["Which practice improves security for an IoT device?","Use unique credentials, updates, and least-privilege access|Use the same public password on every device|Disable updates forever|Expose administrative services to the whole internet by default",0,"Unique credentials, patching, and limiting privileges reduce common compromise paths."],["Why can sending raw sensor data continuously be inefficient?","It may waste bandwidth and energy when summaries would meet the need|Raw data always has zero value|It guarantees sensor accuracy|It removes all storage requirements",0,"Sampling, filtering, aggregation, and event-driven reporting can reduce unnecessary transmissions when the application allows it."],["A 12-bit ADC represents unsigned values from 0 through what maximum code?","4095|2048|4096|1023",0,"A 12-bit unsigned converter has 2^12 = 4096 codes, numbered 0 through 4095."],["An ideal 10-bit ADC spans 0–5 V. What is the approximate voltage step using 1024 levels?","4.88 mV|48.8 mV|0.488 V|0.00488 V is 4.88 V",0,"Step size is approximately 5 V / 1024 = 0.004883 V, or 4.88 mV."],["Which statement best compares analog and digital sensor outputs?","Analog varies continuously over a range; digital output represents discrete states or encoded values|Analog always contains text; digital always contains audio|Digital outputs cannot encode measurements|Analog sensors never require conversion",0,"Analog signals vary continuously; digital interfaces represent information as discrete states or encoded data."],["Why should a microcontroller pin's voltage and current limits be checked before connecting a component?","To avoid damaging the pin or connected hardware|To increase the Wi-Fi password length|To change UDP into TCP|To eliminate the need for a circuit diagram",0,"Electrical limits matter because overvoltage or excessive current can damage components or cause unsafe operation."],["What is a practical benefit of a Raspberry Pi acting as a UDP receiver?","It can collect sensor datagrams and process or log them in software|It guarantees every UDP datagram is delivered|It converts all wireless packets into electricity|It replaces the need for an IP address",0,"A Pi can run a user-space receiver that parses, aggregates, displays, or logs incoming datagrams."],["If a UDP message is 100 bytes and is sent 20 times per second, what is the payload rate?","2,000 bytes/s|200 bytes/s|20 bytes/s|5,000 bytes/s",0,"Payload rate = 100 bytes × 20 messages/s = 2,000 bytes/s, excluding protocol overhead."],["A sensor samples at 4 Hz. What is the interval between consecutive samples?","0.25 seconds|4 seconds|2 seconds|0.04 seconds",0,"Sampling interval is the reciprocal of frequency: 1/4 second = 0.25 seconds."],["A device samples at 50 Hz. How many samples does it collect in 12 seconds if sampling is continuous?","600|50|12|4,200",0,"Sample count = frequency × duration = 50 × 12 = 600."],["Which statement about sampling frequency is correct?","Higher sampling frequency produces more samples per second|Higher sampling frequency always reduces data volume|Sampling frequency is the same as packet latency|Frequency cannot be measured in hertz",0,"Hertz means cycles or samples per second; increasing sample frequency generally increases sample volume if other factors remain constant."],["Why is unit normalization useful when combining sensor datasets?","It prevents comparing unlike scales such as Celsius and Fahrenheit as if they were identical|It makes all readings equal|It removes the need for calibration|It guarantees zero measurement error",0,"Converting measurements to consistent units makes aggregation and comparison meaningful."],["In data analytics, what is an outlier?","An observation unusually far from the expected pattern or distribution|The average of all observations by definition|A mandatory database column|A packet that has no destination address in every case",0,"An outlier is unusually distant from the bulk of data; it may be an error or a meaningful rare event."],["Why should an outlier not always be deleted automatically?","It may represent a real rare event, fault, or important anomaly|Outliers can never be real measurements|Deleting it always improves accuracy|Outliers are identical to missing values",0,"Outliers need context: they can signal sensor errors, but can also be the very event an IoT system is meant to detect."],["Which operation is an example of aggregation?","Calculating the average temperature across ten readings|Changing a timestamp randomly|Copying every record three times|Removing the unit from all values",0,"Aggregation summarizes multiple observations, for example by calculating a mean, minimum, maximum, or count."],["A dashboard shows 18, 19, 20, 19, and 24 °C. What is the mean?","20 °C|19 °C|21 °C|100 °C",0,"The mean is (18 + 19 + 20 + 19 + 24) / 5 = 100 / 5 = 20 °C."],["A sensor reports 10, 12, 14, 16. What is the median?","13|12|14|15",0,"For four sorted values, median is the average of the middle pair: (12 + 14) / 2 = 13."],["Which storage pattern is useful for efficient querying of large timestamped sensor readings?","Store timestamps and measurements in a structured time-series-friendly schema|Put all readings into an unsearchable image file|Discard timestamps before storage|Store every reading only in a device name",0,"A structured schema with timestamps, identifiers, and values supports filtering, aggregation, and time-window queries."],["Why might an IoT application cache a recent sensor value?","To serve a quick recent reading while reducing repeated device or network requests|To ensure the cached value is always current forever|To avoid any expiration policy|To make the sensor stop measuring",0,"Caching can reduce latency and load, but freshness or expiration rules are needed when values change."],["What does data provenance describe?","Where data came from and how it was collected or transformed|The screen brightness of a gateway|The number of pins on an Arduino|Only the final chart color",0,"Provenance records origin and processing history, helping interpret and audit data."],["Why does clock synchronization matter for comparing timestamps from different IoT nodes?","Unsynchronized clocks can make event ordering and latency estimates inaccurate|It increases every sensor's measurement range|It removes all packet loss|It converts a sensor into a router",0,"Comparing event times across nodes is unreliable if their clocks have significant offsets or drift."],["A message leaves node A at 10:00:00.000 and reaches node B at 10:00:00.150 using synchronized clocks. Approximate one-way delay?","150 ms|15 ms|1.5 seconds|0.150 microseconds",0,"The timestamp difference is 0.150 seconds, which equals 150 milliseconds."],["Which is the best example of event-driven reporting?","Send an alert when temperature crosses a defined threshold|Transmit the same value at the fastest possible rate regardless of change|Only send data once every ten years|Ignore all sensor events",0,"Event-driven reporting sends data when a condition occurs, potentially saving energy and bandwidth."],["What is the trade-off of increasing a sensor's sampling rate?","More temporal detail but typically more data and energy use|Less temporal detail and always lower energy use|No change in data volume under any design|It disables all communication",0,"Higher sampling can capture faster changes but usually increases processing, storage, and communication demand."],["Which architecture places computation near sensors instead of relying entirely on a remote cloud?","Edge computing|Batch-only centralized printing|Offline-only paper records|A passive cable",0,"Edge computing performs some processing close to data sources to improve responsiveness or reduce network traffic."],["What is a cloud platform commonly used for in IoT?","Scalable storage, device management, analytics, and application services|Physically sensing temperature without a device|Replacing all local network links by definition|Guaranteeing that no credential can be stolen",0,"Cloud services can provide storage, fleet management, analytics, dashboards, and integration, depending on the system."],["Why are device identifiers useful in an IoT data pipeline?","They associate readings with the correct device or source|They prove a reading is physically accurate|They automatically encrypt all data|They remove the need for timestamps in every use case",0,"Identifiers distinguish sources and help route, filter, correlate, and audit readings."],["Which is an example of a privacy concern in IoT?","Fine-grained location or activity data may reveal personal behavior|Sensor data can never relate to a person|Encryption makes collection notices unnecessary|Only broken devices can collect personal data",0,"IoT data can reveal location, routines, occupancy, or health-related patterns, so collection and access need care."],["What does encryption primarily help protect?","Confidentiality of data against unauthorized reading|Accuracy of the physical sensor calibration|Battery capacity|The order of UDP packets",0,"Encryption protects information from being read by parties lacking the appropriate key; it does not by itself guarantee accuracy or availability."],["What is authentication intended to establish?","The identity of a user, device, or service|The physical temperature of a room|The number of bytes per second|Whether a chart is a line chart",0,"Authentication checks that an entity is who or what it claims to be."],["Why is least privilege a useful IoT security principle?","Each component receives only the permissions needed for its role|Every device receives administrator access|Credentials are shared publicly|All network traffic is disabled permanently",0,"Least privilege limits the damage if a component or credential is compromised."],["Which failure mode is particularly relevant to remote IoT deployments?","A device may be physically difficult to access for repair or battery replacement|Remote devices never lose power|All networks have perfect coverage|Sensors can always be replaced instantly",0,"Remote or harsh deployments make maintenance costly, so power, diagnostics, reliability, and recovery planning matter."],["What is a benefit of monitoring device health metrics such as battery level and connectivity?","It can help identify failures before the application stops working|It guarantees every device will never fail|It makes sensor measurements unnecessary|It removes all need for maintenance",0,"Health telemetry supports early warnings and maintenance planning, although it cannot prevent every failure."],["In a wireless network, what can happen when many nodes transmit simultaneously on the same channel?","Collisions or contention can reduce successful delivery and increase delay|All packets are guaranteed to arrive sooner|Radio interference becomes impossible|Bandwidth automatically becomes infinite",0,"Shared wireless media require coordination; contention and interference can cause retries, loss, and delay."],["What is the main purpose of a MAC protocol in a shared wireless medium?","Coordinate access to the communication channel|Define the meaning of every application-level temperature field|Calibrate the sensor's voltage output|Store data permanently in the cloud",0,"Medium access control coordinates when nodes use a shared channel to reduce or manage collisions and contention."],["Why can multi-hop routing help a wireless sensor network?","A node can forward data through intermediate nodes when direct delivery is unsuitable|It guarantees zero delay and zero energy use|It removes the need for routing decisions|It ensures every node must reach the cloud directly",0,"Multi-hop paths can extend connectivity or reduce per-link transmission power, though they add forwarding overhead and possible delay."],["What is a possible disadvantage of multi-hop routing?","Intermediate nodes spend energy forwarding others' traffic|It always needs fewer transmissions than every direct route|It makes topology irrelevant|It prevents all packet loss",0,"Forwarders consume energy and may become bottlenecks or single points of failure on a route."],["What does network topology describe?","How network nodes and links are arranged or connected|The units used for humidity|The source code indentation style|The color palette of a dashboard",0,"Topology describes connectivity and arrangement, such as star, mesh, tree, or bus."],["In a star topology, what is a common risk if the central coordinator fails?","Connected nodes may lose their communication path through the center|Every node automatically becomes a new coordinator|The network turns into a mesh without configuration|The battery voltage doubles",0,"A star often depends on its central node, so its failure can disconnect the spokes from one another or upstream services."],["Which topology generally provides multiple possible paths between nodes when links are available?","Mesh|Single-link line with no alternate route|Pure star with no peer links|Point-to-point with one link only",0,"A mesh can provide alternate paths, improving resilience at the cost of additional links and routing complexity."],["What is the main purpose of a protocol in IoT communication?","Define rules and formats that enable systems to exchange and interpret messages|Guarantee all physical sensors are identical|Replace all application requirements|Make every network use the same frequency",0,"Protocols define communication behavior, message formats, addressing, sequencing, and other interoperability rules."],["What does interoperability mean in an IoT system?","Different components can work together and exchange usable information|Every device has the same manufacturer|All components use the same programming language|Data is never transformed",0,"Interoperability means systems can exchange and use information despite differences in devices, vendors, or technologies."],["A temperature is reported as 25 without a unit. Why is this ambiguous?","It could mean Celsius, Fahrenheit, or another scale, so interpretation is unclear|Every temperature unit has the same numeric scale|A unit is only needed for integers|The number automatically means Kelvin",0,"Measurements need units or a documented schema; the numeric value alone is insufficient to interpret a temperature reliably."],["Which practice helps different IoT services interpret a payload consistently?","Use a documented schema with explicit field names, units, and types|Rely on undocumented field order|Change key meanings between messages|Send numeric values without any context",0,"A shared, documented schema reduces ambiguity about names, types, units, and optional fields."],["Why might an IoT system use a message broker?","Decouple data producers from consumers and distribute messages to interested services|Replace every physical sensor|Guarantee all messages are correct without validation|Make timestamps unnecessary",0,"A broker can buffer, route, or fan out messages so producers and consumers need not communicate directly."],["Which is a sensible approach when network connectivity temporarily disappears?","Buffer important readings locally and retry according to a policy|Discard every reading without checking importance|Increase sensor voltage until the network returns|Assume the cloud received the data",0,"Local buffering and controlled retries can improve resilience; policies should account for storage limits and duplicate handling."],["Why should a retrying client use unique message IDs or idempotent operations where appropriate?","To prevent retries from causing duplicate effects or records|To guarantee the first attempt never fails|To make messages larger by design|To disable server-side validation",0,"Retries can repeat operations; IDs or idempotent handling help the receiver recognize repeats and avoid duplicate effects."],["What is the best reason to separate data collection from data visualization?","It allows storage and processing to continue even when a dashboard is unavailable|Charts can never use stored data|Collection must always depend on browser state|It eliminates all network security needs",0,"A decoupled pipeline can continue ingesting and storing data even when the UI is offline or being updated."],["A dashboard's total count is much higher than expected because clients retry on timeout. What should be investigated first?","Whether duplicate events are being ingested and deduplicated correctly|Whether the chart uses a green color|Whether the sensor's enclosure is round|Whether the page title is too short",0,"Retries can deliver the same logical event more than once; event IDs and idempotent ingestion should be checked."],["Which statement best describes predictive maintenance using IoT data?","Use sensor trends or anomalies to estimate when equipment may need attention|Wait for every component to fail before collecting data|Replace sensors with fixed random values|Use only device color to predict breakdowns",0,"Predictive maintenance analyzes condition data and patterns to identify elevated failure risk or maintenance needs."],["Which is a useful metric for evaluating an alerting system?","False-positive and false-negative rates, alongside detection delay|The font used in the dashboard heading only|Number of colors in the logo|The length of a device nickname",0,"Alert quality involves missed events, false alarms, and how quickly true events are detected."],["An alert threshold is set too low. What is a likely outcome?","More false alarms from ordinary fluctuations|No alerts under any conditions|Perfect accuracy in all environments|The sensor stops collecting data",0,"A threshold that is too sensitive may trigger on normal variation, increasing false positives."],["What is the role of a baseline in anomaly detection?","Provide a reference pattern against which new observations can be compared|Guarantee that no anomalies occur|Replace the measured values with constants|Specify only the device's IP address",0,"A baseline captures expected behavior; deviations can then be examined as potential anomalies."],["Which conclusion is safest when a single IoT reading suddenly spikes?","Check context, neighboring readings, sensor health, and corroborating signals before deciding|Assume it is certainly a real emergency|Delete it immediately without logging|Assume all later readings are invalid",0,"A spike may be a real event or a sensor/communication artifact; context and corroboration help distinguish them."],["Why can aggregate averages hide important IoT events?","Short-lived extremes may disappear in the mean|Averages always equal the maximum|Aggregates cannot contain numbers|A mean is a security protocol",0,"Averages smooth variation and can hide peaks; minimum/maximum, percentiles, and event detection may also be needed."],["A pipeline stores 6 readings per minute from each of 25 devices. How many readings arrive in 40 minutes, assuming none are lost?","6,000|1,000|150|60,000",0,"Total = 6 readings/min/device × 25 devices × 40 minutes = 6,000 readings."],["A link carries 2 Mbit/s. Approximately how long to transmit 5 Mbit, ignoring overhead?","2.5 seconds|0.4 seconds|10 seconds|1 second",0,"Time = data / rate = 5 Mbit / 2 Mbit/s = 2.5 seconds."],["A system's end-to-end delay is 20 ms processing + 35 ms transmission/queueing + 45 ms network delay. What is total delay if components are additive?","100 ms|80 ms|55 ms|900 ms",0,"Add the components: 20 + 35 + 45 = 100 ms."],["A device uses 80 mA while active and 2 mA while asleep. It is active 10% of the time. Approximate average current?","9.8 mA|8.0 mA|41 mA|2.0 mA",0,"Average current = 0.10 × 80 + 0.90 × 2 = 8 + 1.8 = 9.8 mA."],["A 500-byte payload is sent 4 times per second. Ignoring headers, what is the data rate in bits/s?","16,000 bit/s|2,000 bit/s|500 bit/s|8,000 bit/s",0,"500 bytes × 4/s × 8 bits/byte = 16,000 bit/s."],["Which statement about a system's sampling rate and network packet rate is correct?","They may differ because one packet can contain multiple samples|They must always be identical|Packet rate is always higher than sample rate|Neither can be measured",0,"A sender may batch several samples into one packet, or use a separate packetization strategy, so rates need not match."],["Why can batching multiple readings into one packet reduce overhead?","Protocol headers are amortized across multiple readings|It removes all transmission delay|It guarantees no data loss|It increases the number of headers per reading",0,"Batching can reduce per-reading header overhead, but may add waiting time and increase the amount lost if a packet drops."],["What is a trade-off of batching readings?","Lower overhead but potentially greater delay before a batch is sent|Higher overhead and zero delay in all cases|No effect on latency or efficiency|It makes data impossible to decode",0,"Waiting to fill a batch can reduce overhead while adding delay, so the batch size should match application needs."],["In an SDN-enabled IoT network, where should an application typically request a high-level network policy?","Through a northbound controller interface|By rewriting a sensor's measured temperature|Through the switch power supply|By changing the humidity unit",0,"Applications generally use northbound interfaces to express policy to the SDN controller."],["A switch receives a packet with no matching flow entry. What happens next depends on configuration; which is a possible behavior?","Send a packet-in or otherwise invoke the configured miss handling|The packet must always be converted to TCP|The switch must reboot|The controller's northbound API automatically changes the sensor",0,"Table-miss behavior is configurable; a switch may send the packet to a controller, drop it, or apply another configured action."],["Why is controller-to-device latency important in SDN?","Installing or changing forwarding rules may be delayed when the control path is slow|It changes the physical sensor calibration|It makes packet headers unnecessary|It guarantees that every flow expires instantly",0,"Control-path delay can affect how quickly policies and new flow rules take effect, especially for reactive decisions."],["What is a good reason to keep some urgent logic at the edge even when SDN or cloud control exists?","Safety-critical local responses may need to continue during network or controller outages|The cloud always has a slower clock|Edge devices cannot communicate|Central policies cannot ever be useful",0,"Local fallback logic can preserve essential behavior during disconnection or control-plane failure."],["What is a sensible design for a networked activity-monitoring system?","Collect signals, process or aggregate them, and send relevant events to an authorized consumer|Record personal activity publicly without access controls|Treat every raw sample as a final conclusion|Skip validation and timestamps",0,"A monitoring pipeline needs sensing, suitable processing, reliable event interpretation, and privacy-aware delivery."],["Why should activity-monitoring systems consider privacy by design?","Behavioral patterns can be sensitive even when data looks like ordinary sensor readings|Only names and passwords can be private|Privacy is unnecessary if the device is small|Encryption alone answers every privacy question",0,"Occupancy, movement, and routine patterns can reveal sensitive behavior; minimization, access controls, retention limits, and transparency matter."],["Which approach is appropriate when an IoT analytics result will trigger a physical action?","Validate inputs and apply safety limits before executing the action|Execute every model output without bounds|Ignore actuator state|Assume network messages are always trustworthy",0,"Physical actions should be bounded and validated because sensors, networks, and analytic outputs can fail or be manipulated."],["A sensor sends 300 records, 15 are confirmed duplicates, and 5 distinct records are invalid. How many valid unique records remain?","280|285|295|320",0,"Remove the 15 duplicate copies and 5 invalid records: 300 − 15 − 5 = 280."],["Which statement best captures the purpose of IoT data analytics?","Turn collected data into summaries, patterns, alerts, or decisions that support a goal|Collect the largest possible data volume regardless of use|Replace sensors with charts|Guarantee every prediction is correct",0,"Analytics extracts useful information from measurements to support monitoring, understanding, and decisions; its quality depends on data and methods."]].slice(0, 100);
  const bank = raw.map((item, index) => {
    const [question, optionText, answer, explanation] = item;
    const originalOptions = optionText.split("|");
    const shift = index % originalOptions.length;
    const options = originalOptions.slice(shift).concat(originalOptions.slice(0, shift));
    const correctAnswer = (answer - shift + originalOptions.length) % originalOptions.length;
    return {
      id: index + 1,
      topic: index < 20 ? "IoT fundamentals & communication" : index < 30 ? "Arduino, Raspberry Pi & UDP" : index < 40 ? "Software-Defined Networking" : index < 60 ? "Data handling & analytics" : index < 70 ? "Sensors, sampling & edge computing" : index < 85 ? "Security, WSNs & interoperability" : "Scenario-based & numerical practice",
      question, options, answer: correctAnswer, explanation
    };
  });
  const TOTAL_SECONDS = 120 * 60;
  const intro = document.getElementById("intro");
  const test = document.getElementById("test");
  const results = document.getElementById("results");
  const startBtn = document.getElementById("start-btn");
  const timerEl = document.getElementById("timer");
  const countEl = document.getElementById("question-count");
  const progressBar = document.getElementById("progress-bar");
  const topicEl = document.getElementById("topic-label");
  const questionEl = document.getElementById("question-text");
  const optionsEl = document.getElementById("options");
  const gridEl = document.getElementById("question-grid");
  const answeredCountEl = document.getElementById("answered-count");
  const prevBtn = document.getElementById("prev-btn");
  const nextBtn = document.getElementById("next-btn");
  const submitBtn = document.getElementById("submit-btn");
  const answers = Array(bank.length).fill(null);
  let current = 0;
  let secondsLeft = TOTAL_SECONDS;
  let ticker = null;
  let startedAt = null;
  let finishedAt = null;
  let submitted = false;

  const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" }[char]));
  const formatTime = total => {
    const mins = Math.floor(total / 60);
    const secs = total % 60;
    return String(mins).padStart(2, "0") + ":" + String(secs).padStart(2, "0");
  };
  function updateTimer() {
    timerEl.textContent = formatTime(secondsLeft);
    timerEl.classList.toggle("warning", secondsLeft <= 300);
  }
  function updateProgress() {
    const answered = answers.filter(value => value !== null).length;
    answeredCountEl.textContent = answered + " of " + bank.length + " answered";
    progressBar.style.width = ((current + 1) / bank.length * 100) + "%";
    gridEl.querySelectorAll(".q-jump").forEach((button, index) => {
      button.classList.toggle("answered", answers[index] !== null);
      button.classList.toggle("current", index === current);
      button.setAttribute("aria-current", index === current ? "step" : "false");
    });
  }
  function renderQuestion() {
    const item = bank[current];
    countEl.textContent = "Question " + (current + 1) + " of " + bank.length;
    topicEl.textContent = item.topic;
    questionEl.textContent = item.question;
    optionsEl.innerHTML = "";
    item.options.forEach((option, index) => {
      const label = document.createElement("label");
      label.className = "option" + (answers[current] === index ? " selected" : "");
      const input = document.createElement("input");
      input.type = "radio";
      input.name = "answer-" + current;
      input.value = String(index);
      input.checked = answers[current] === index;
      input.setAttribute("aria-label", "Option " + String.fromCharCode(65 + index));
      input.addEventListener("change", () => {
        answers[current] = index;
        renderQuestion();
      });
      const letter = document.createElement("span");
      letter.className = "letter";
      letter.textContent = String.fromCharCode(65 + index) + ".";
      const text = document.createElement("span");
      text.textContent = option;
      label.append(input, letter, text);
      optionsEl.appendChild(label);
    });
    prevBtn.disabled = current === 0;
    prevBtn.style.opacity = current === 0 ? ".45" : "1";
    nextBtn.textContent = current === bank.length - 1 ? "Last question" : "Next →";
    updateProgress();
  }
  function buildNavigator() {
    gridEl.innerHTML = "";
    bank.forEach((item, index) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "q-jump";
      button.textContent = String(index + 1);
      button.setAttribute("aria-label", "Go to question " + (index + 1));
      button.addEventListener("click", () => { current = index; renderQuestion(); window.scrollTo({ top: 0, behavior: "smooth" }); });
      gridEl.appendChild(button);
    });
  }
  function begin() {
    intro.classList.add("hidden");
    test.classList.remove("hidden");
    current = 0;
    startedAt = Date.now();
    buildNavigator();
    renderQuestion();
    updateTimer();
    ticker = window.setInterval(() => {
      secondsLeft -= 1;
      updateTimer();
      if (secondsLeft <= 0) submitTest(true);
    }, 1000);
  }
  function submitTest(auto = false) {
    if (submitted) return;
    const unanswered = answers.filter(value => value === null).length;
    if (!auto && unanswered > 0 && !window.confirm("You have " + unanswered + " unanswered question(s). Submit the test anyway?")) return;
    if (!auto && !window.confirm("Submit your test now? You will see the score and explanations after submission.")) return;
    submitted = true;
    finishedAt = Date.now();
    if (ticker) window.clearInterval(ticker);
    test.classList.add("hidden");
    results.classList.remove("hidden");
    renderResults(auto);
    window.scrollTo({ top: 0, behavior: "smooth" });
  }
  function renderResults(auto) {
    const score = bank.reduce((sum, item, index) => sum + (answers[index] === item.answer ? 1 : 0), 0);
    const answered = answers.filter(value => value !== null).length;
    const elapsed = Math.min(TOTAL_SECONDS, Math.floor((finishedAt - startedAt) / 1000));
    document.getElementById("result-title").textContent = auto ? "Time is up!" : "Your results";
    document.getElementById("result-summary").textContent = "Review the explanations below to understand the correct concept and why each alternative does not fit.";
    document.getElementById("score-value").textContent = score + " / " + bank.length;
    document.getElementById("percentage-value").textContent = Math.round(score / bank.length * 100) + "%";
    document.getElementById("answered-value").textContent = answered + " / " + bank.length;
    document.getElementById("time-value").textContent = formatTime(elapsed);
    const review = document.getElementById("review-list");
    review.innerHTML = "";
    bank.forEach((item, index) => {
      const userAnswer = answers[index];
      const correctText = item.options[item.answer];
      const card = document.createElement("article");
      card.className = "review-item";
      const heading = document.createElement("h3");
      heading.textContent = (index + 1) + ". " + item.question;
      const meta = document.createElement("div");
      meta.className = "review-meta";
      meta.textContent = item.topic + " · " + (userAnswer === null ? "Not answered" : userAnswer === item.answer ? "Correct" : "Incorrect");
      card.append(heading, meta);
      item.options.forEach((option, optionIndex) => {
        const line = document.createElement("div");
        line.className = "review-option" + (optionIndex === item.answer ? " correct" : "") + (userAnswer === optionIndex && optionIndex !== item.answer ? " chosen-wrong" : "");
        const status = document.createElement("strong");
        status.textContent = optionIndex === item.answer ? "✓ Correct answer" : userAnswer === optionIndex ? "✕ Your answer" : "Option " + String.fromCharCode(65 + optionIndex);
        const body = document.createElement("span");
        body.textContent = option;
        const reason = document.createElement("p");
        reason.className = "option-reason";
        reason.textContent = optionIndex === item.answer
          ? "Why this is correct: " + item.explanation
          : "Why this is incorrect: This choice does not satisfy the key requirement in the question. " + item.explanation;
        line.append(status, body, reason);
        card.appendChild(line);
      });
      const explain = document.createElement("p");
      explain.className = "explanation";
      explain.textContent = "Why: " + item.explanation + " The other options do not satisfy this key concept; the correct answer is " + String.fromCharCode(65 + item.answer) + ": " + correctText + ".";
      card.appendChild(explain);
      review.appendChild(card);
    });
  }
  function resetTest() {
    answers.fill(null);
    current = 0;
    secondsLeft = TOTAL_SECONDS;
    submitted = false;
    startedAt = null;
    finishedAt = null;
    if (ticker) window.clearInterval(ticker);
    results.classList.add("hidden");
    test.classList.add("hidden");
    intro.classList.remove("hidden");
    window.scrollTo({ top: 0, behavior: "smooth" });
  }
  startBtn.addEventListener("click", begin);
  prevBtn.addEventListener("click", () => { if (current > 0) { current--; renderQuestion(); } });
  nextBtn.addEventListener("click", () => { if (current < bank.length - 1) { current++; renderQuestion(); } });
  submitBtn.addEventListener("click", () => submitTest(false));
  document.getElementById("retake-btn").addEventListener("click", resetTest);
})();